// V80 · Monitoramento Inteligente — análises auditáveis sobre o mesmo recorte filtrado.
(()=>{
const $=id=>document.getElementById(id); if(!$('v80AiDiff'))return;
const esc=s=>String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const brl=v=>Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const dbr=s=>s?new Date(s+'T12:00:00').toLocaleDateString('pt-BR'):'—';
function params(mode){const q=new URLSearchParams({mode,start:$('fStart').value,end:$('fEnd').value,company:$('fCompany').value,line:$('fLine').value,station:$('fStation').value,terminal:$('fAtm').value,status:$('fStatus').value,programming:$('fProgramming').value,difference:$('fDifference').value});return q}
function bars(rows,{money=false,kind=''}={}){rows=rows||[];if(!rows.length)return '<p class="muted">Sem dados para este gráfico.</p>';const max=Math.max(...rows.map(x=>Math.abs(Number(x.value)||0)),1);return `<div class="v80BarList">${rows.map(x=>`<div class="v80Bar ${kind}"><span class="v80BarLabel" title="${esc(x.label)}">${esc(x.label)}</span><div class="v80BarTrack"><div class="v80BarFill" style="width:${Math.max(2,Math.abs(Number(x.value)||0)/max*100)}%"></div></div><b>${money?brl(x.value):Number(x.value||0).toLocaleString('pt-BR')}</b></div>`).join('')}</div>`}
function kpi(label,value,cls=''){return `<div class="v80AiKpi ${cls}"><small>${esc(label)}</small><strong>${value}</strong></div>`}
function renderDiff(d){const s=d.summary,c=d.charts||{};return `<div class="v80AiKpis">${kpi('Coletas/ocorrências',s.collections,'ai')}${kpi('Negativas',s.negative,'neg')}${kpi('Zeradas',s.zero,'zero')}${kpi('Positivas',s.positive,'pos')}${kpi('Saldo A − D',brl(s.net_difference),Number(s.net_difference)<0?'neg':'zero')}${kpi('Diferença absoluta',brl(s.absolute_difference),'warn')}</div><div class="v80AiGrid"><section class="v80AiPanel"><h3>Leitura inteligente do período</h3>${(d.insights||[]).map(x=>`<div class="v80Insight">${esc(x)}</div>`).join('')}</section><section class="v80AiPanel"><h3>Distribuição das divergências</h3>${bars(c.difference_distribution)}</section><section class="v80AiPanel"><h3>Maiores diferenças negativas</h3>${bars(c.negative_top,{money:true,kind:'neg'})}</section><section class="v80AiPanel"><h3>Concentração absoluta por localidade</h3>${bars(c.by_station,{money:true,kind:'info'})}</section><section class="v80AiPanel"><h3>Concentração absoluta por linha</h3>${bars(c.by_line,{money:true})}</section><section class="v80AiPanel"><h3>Concentração absoluta por operadora</h3>${bars(c.by_company,{money:true,kind:'info'})}</section></div><section class="v80AiPanel" style="margin-top:14px"><h3>Casos negativos que exigem atenção</h3><div class="v80AiTable"><table><thead><tr><th>ATM</th><th>Localidade</th><th>Linha</th><th>Data</th><th>Declarado</th><th>Apurado</th><th>Diferença</th><th>% sobre declarado</th></tr></thead><tbody>${(d.negative_rows||[]).map(x=>`<tr><td><b>${esc(x.terminal)}</b></td><td>${esc(x.station)}</td><td>${esc(x.line)}</td><td>${dbr(x.date)}</td><td>${brl(x.declared_amount)}</td><td>${brl(x.processed_amount)}</td><td style="font-weight:800;color:#b91c1c">${brl(x.difference)}</td><td>${x.difference_pct==null?'—':Number(x.difference_pct).toLocaleString('pt-BR',{maximumFractionDigits:2})+'%'}</td></tr>`).join('')||'<tr><td colspan="8">Nenhuma diferença negativa no filtro atual.</td></tr>'}</tbody></table></div></section><div class="v80Method"><b>Metodologia:</b> ${esc(d.methodology?.financial||'')} A interpretação usa os resultados calculados; não recalcula valores financeiros.</div>`}
function renderOcc(d){const s=d.summary,c=d.charts||{};return `<div class="v80AiKpis">${kpi('Ocorrências analisadas',s.observations,'ai')}${kpi('Falha fechadura/cofre',s.lock_failures,'neg')}${kpi('Coletas/ocorrências',s.collections,'info')}${kpi('Negativas',s.negative,'neg')}${kpi('Zeradas',s.zero,'zero')}${kpi('Positivas',s.positive,'pos')}</div><div class="v80AiGrid"><section class="v80AiPanel"><h3>Leitura inteligente das observações</h3>${(d.insights||[]).map(x=>`<div class="v80Insight">${esc(x)}</div>`).join('')}</section><section class="v80AiPanel"><h3>Ocorrências por categoria</h3>${bars(c.occurrence_categories)}</section><section class="v80AiPanel"><h3>Localidades com falha de fechadura/cofre</h3>${bars(c.lock_locations,{kind:'neg'})}</section><section class="v80AiPanel"><h3>Contexto financeiro do mesmo recorte</h3>${bars(c.difference_distribution)}</section></div><section class="v80AiPanel" style="margin-top:14px"><h3>Ocorrências classificadas</h3><div class="v80AiTable"><table><thead><tr><th>Categoria</th><th>ATM</th><th>Localidade</th><th>Linha</th><th>Data</th><th>Status</th><th>Observação</th></tr></thead><tbody>${(d.occurrence_rows||[]).map(x=>`<tr><td><b>${esc(x.category)}</b></td><td>${esc(x.terminal)}</td><td>${esc(x.station)}</td><td>${esc(x.line)}</td><td>${dbr(x.date)}</td><td>${esc(x.status)}</td><td style="white-space:normal;min-width:280px">${esc(x.note||x.occurrence||'—')}</td></tr>`).join('')||'<tr><td colspan="7">Nenhuma observação no filtro atual.</td></tr>'}</tbody></table></div></section><div class="v80Method"><b>Metodologia:</b> ${esc(d.methodology?.occurrences||'')} Clique/consulte a tabela para auditar os registros que originaram cada categoria.</div>`}
async function open(mode){$('v80AiModal').classList.add('open');$('v80AiTitle').textContent=mode==='occurrences'?'Análise IA · Ocorrências':'Análise IA · Divergências';$('v80AiSub').textContent=`Período ${dbr($('fStart').value)} a ${dbr($('fEnd').value)} · respeitando os filtros ativos.`;$('v80AiBody').innerHTML='<div class="v80Loading">Calculando indicadores e correlações do recorte...</div>';try{const r=await fetch('/api/financeiro/coletas/v80/analise?'+params(mode),{cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw Error(d.error||'Falha na análise');$('v80AiBody').innerHTML=mode==='occurrences'?renderOcc(d):renderDiff(d)}catch(e){$('v80AiBody').innerHTML=`<div class="v80Insight" style="border-left-color:#dc2626">${esc(e.message||'Falha ao gerar análise.')}</div>`}}
$('v80AiDiff').onclick=()=>open('divergences');$('v80AiOcc').onclick=()=>open('occurrences');$('v80AiClose').onclick=()=>$('v80AiModal').classList.remove('open');$('v80AiModal').addEventListener('mousedown',e=>{if(e.target===$('v80AiModal'))$('v80AiModal').classList.remove('open')});
})();

// V80 REV1 · importação incremental de transações e planejamento de auditoria.
(()=>{
const $=id=>document.getElementById(id); if(!$('v801TxStatus'))return;
const esc=s=>String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const dbr=s=>{if(!s)return '—';const d=new Date(s);return Number.isNaN(d.getTime())?String(s):d.toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})};
const daybr=s=>s?new Date(s+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'short',day:'2-digit',month:'2-digit'}):'—';
let txStatus=null, pollTimer=null;
function historyHtml(d){const rows=d.history||[];return `<div class="v801Kpis"><article><small>Transações armazenadas</small><strong>${Number(d.total_transactions||0).toLocaleString('pt-BR')}</strong></article><article><small>Última carga</small><strong style="font-size:15px">${dbr(d.latest_import_at)}</strong></article><article><small>Base até</small><strong style="font-size:15px">${dbr(d.latest_transaction_at)}</strong></article><article><small>Último arquivo</small><strong style="font-size:13px">${esc(d.latest_file||'—')}</strong></article></div><div class="v801Table"><table><thead><tr><th>Data/hora</th><th>Arquivo</th><th>Layout</th><th>Lidas</th><th>Novas</th><th>Atualizadas/já conhecidas</th><th>Erros</th><th>Usuário</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${dbr(x.at)}</td><td>${esc(x.file||'—')}</td><td>${esc(x.layout||'—')}</td><td>${Number(x.rows_read||0).toLocaleString('pt-BR')}</td><td>${Number(x.inserted||0).toLocaleString('pt-BR')}</td><td>${Number((x.updated||0)+(x.duplicates||0)).toLocaleString('pt-BR')}</td><td>${Number(x.errors||0).toLocaleString('pt-BR')}</td><td>${esc(x.user||'—')}</td></tr>`).join('')||'<tr><td colspan="8">Nenhuma importação registrada ainda.</td></tr>'}</tbody></table></div><p class="v79Footer">O importador aceita o relatório R0050 no formato atual e o layout transacional legado. Linhas repetidas não são duplicadas.</p>`}
async function loadTxStatus(showHistory=false){try{const r=await fetch('/api/financeiro/coletas/v80/transacoes/status',{cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw Error(d.error||'Falha');txStatus=d;$('v801LastImport').textContent=d.latest_import_at?dbr(d.latest_import_at):'Nenhuma carga';$('v801LastFile').textContent=d.latest_file||'—';$('v801LastTx').textContent=d.latest_transaction_at?dbr(d.latest_transaction_at):'—';$('v801TxCount').textContent=Number(d.total_transactions||0).toLocaleString('pt-BR');$('v801TxStatus').title='Clique para ver o histórico de importações';$('v801TxStatus').style.cursor='pointer';if(showHistory){$('v801TxHistoryBody').innerHTML=historyHtml(d);$('v801TxHistoryModal').classList.add('open')}}catch(e){$('v801LastImport').textContent='Status indisponível'}}
$('v801TxStatus').addEventListener('click',()=>loadTxStatus(true));
$('v801TxHistoryClose')?.addEventListener('click',()=>$('v801TxHistoryModal').classList.remove('open'));
$('v801TxHistoryModal')?.addEventListener('mousedown',e=>{if(e.target===$('v801TxHistoryModal'))$('v801TxHistoryModal').classList.remove('open')});
async function poll(jobId){clearTimeout(pollTimer);try{const r=await fetch(`/api/financeiro/apuracao/importar/${encodeURIComponent(jobId)}/status`,{cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw Error(d.error||'Falha ao consultar importação');const box=$('v801ImportProgress');box.style.display='block';box.innerHTML=`<b>${esc(d.status||'PROCESSANDO')}</b> · ${esc(d.message||'')}<br><span>${Number(d.rows_processed||0).toLocaleString('pt-BR')} / ${Number(d.rows_total||0).toLocaleString('pt-BR')} linhas · novas ${Number(d.rows_inserted||0).toLocaleString('pt-BR')} · erros ${Number(d.rows_errors||0).toLocaleString('pt-BR')} · ${Number(d.progress||0)}%</span>`;if(d.status==='CONCLUIDO'){box.innerHTML+=`<br><b>Importação concluída.</b>`;await loadTxStatus();setTimeout(()=>box.style.display='none',9000);return}if(d.status==='FALHOU'){box.innerHTML+=`<br><b style="color:#b91c1c">${esc(d.error||'Importação interrompida.')}</b>`;return}pollTimer=setTimeout(()=>poll(jobId),1800)}catch(e){$('v801ImportProgress').style.display='block';$('v801ImportProgress').textContent=e.message}}
const importBtn=$('v801TxImport'), file=$('v801TxFile');
if(importBtn&&file){importBtn.onclick=()=>file.click();file.onchange=async()=>{const f=file.files?.[0];if(!f)return;const fd=new FormData();fd.append('file',f);$('v801ImportProgress').style.display='block';$('v801ImportProgress').innerHTML=`Enviando <b>${esc(f.name)}</b>…`;try{const r=await fetch('/api/financeiro/apuracao/importar',{method:'POST',body:fd}),d=await r.json();if(!r.ok||!d.ok)throw Error(d.error||'Falha ao iniciar importação');poll(d.job_id)}catch(e){$('v801ImportProgress').innerHTML=`<b style="color:#b91c1c">${esc(e.message)}</b>`}finally{file.value=''}}}
async function resumeActive(){if(!importBtn)return;try{const r=await fetch('/api/financeiro/apuracao/importar/active',{cache:'no-store'}),d=await r.json();if(r.ok&&d.ok&&d.job?.job_id)poll(d.job.job_id)}catch(_){}}
function planHtml(d){const s=d.summary||{},days=d.days||[],max=Math.max(...days.map(x=>Number(x.auditors||0)),1);return `<div class="v801Kpis"><article><small>Dias com coleta</small><strong>${Number(s.days||0)}</strong></article><article><small>Coletas previstas</small><strong>${Number(s.collections||0).toLocaleString('pt-BR')}</strong></article><article><small>Pico de auditores</small><strong>${Number(s.peak_auditors||0)}</strong></article><article><small>Dia(s) de pico</small><strong style="font-size:14px">${(s.peak_days||[]).map(x=>daybr(x)).join(' · ')||'—'}</strong></article></div><section class="v80AiPanel" style="margin-top:14px"><h3>Pessoas necessárias por dia</h3><div class="v801Bars">${days.map(x=>`<div class="v801Bar"><span>${daybr(x.date)}</span><div class="v801Track"><div class="v801Fill" style="width:${Math.max(2,Number(x.auditors||0)/max*100)}%"></div></div><b>${x.auditors} pessoa(s)</b></div>`).join('')||'<p class="muted">Nenhuma programação no período.</p>'}</div></section><div class="v801Table"><table><thead><tr><th>Data</th><th>Coletas</th><th>Localidades</th><th>Regulares</th><th>Extras</th><th>Reagendadas</th><th>Pessoas mínimas</th><th>Detalhamento</th></tr></thead><tbody>${days.map(x=>`<tr><td><b>${daybr(x.date)}</b></td><td>${x.collections}</td><td>${x.localities}</td><td>${x.regular}</td><td>${x.extra}</td><td>${x.rescheduled}</td><td><b>${x.auditors}</b></td><td style="white-space:normal;min-width:320px">${(x.details||[]).map(z=>`<b>${esc(z.station)}</b>: ${z.atm_count} ATM(s) → 1 auditor`).join('<br>')}</td></tr>`).join('')||'<tr><td colspan="8">Sem programação no período.</td></tr>'}</tbody></table></div><p class="v80Method"><b>Regra V80 REV1:</b> ${esc(d.rule||'')} O cálculo não otimiza deslocamento entre localidades nem sobreposição de horários; isso pode ser evoluído posteriormente.</p>`}
async function openPlan(){const start=$('fStart')?.value,end=$('fEnd')?.value;if(!start||!end)return;$('v801PlanModal').classList.add('open');$('v801PlanSub').textContent=`Período ${new Date(start+'T12:00:00').toLocaleDateString('pt-BR')} a ${new Date(end+'T12:00:00').toLocaleDateString('pt-BR')} · 1 auditor por localidade/dia.`;$('v801PlanBody').innerHTML='<div class="v80Loading">Calculando agenda e necessidade mínima de equipe…</div>';try{const r=await fetch(`/api/financeiro/coletas/v80/planejamento-auditoria?start=${encodeURIComponent(start)}&end=${encodeURIComponent(end)}`,{cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw Error(d.error||'Falha no planejamento');$('v801PlanBody').innerHTML=planHtml(d)}catch(e){$('v801PlanBody').innerHTML=`<div class="v80Insight" style="border-left-color:#dc2626">${esc(e.message)}</div>`}}
$('v801Planning')?.addEventListener('click',openPlan);$('v801PlanningProgram')?.addEventListener('click',openPlan);$('v801PlanClose')?.addEventListener('click',()=>$('v801PlanModal').classList.remove('open'));$('v801PlanModal')?.addEventListener('mousedown',e=>{if(e.target===$('v801PlanModal'))$('v801PlanModal').classList.remove('open')});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){[$('v801PlanModal'),$('v801TxHistoryModal')].forEach(x=>x?.classList.remove('open'))}});
loadTxStatus();resumeActive();
})();
